'use strict';

// PNG file signature: 137 'P' 'N' 'G' '\r' '\n' 0x1A '\n'
const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/**
 * Hand-rolled PNG IHDR parser.
 *
 * Layout of a PNG stream:
 *   bytes [0..7]   : signature (see above)
 *   bytes [8..11]  : first chunk length (big-endian uint32), must be 13 for IHDR
 *   bytes [12..15] : chunk type, ASCII "IHDR"
 *   bytes [16..19] : width  (big-endian uint32)
 *   bytes [20..23] : height (big-endian uint32)
 *
 * We only need the header bytes; the rest of the image (IDAT, CRCs, ...)
 * does not have to be valid for this check to work.
 *
 * @param {Buffer} buf
 * @returns {{ width: number, height: number } | null} null if not parseable as a PNG
 */
function parsePngIhdr(buf) {
  if (!Buffer.isBuffer(buf) || buf.length < 24) return null;
  if (!buf.subarray(0, 8).equals(PNG_SIGNATURE)) return null;

  // First chunk must be exactly 13 bytes long and named IHDR
  if (buf.readUInt32BE(8) !== 13) return null;
  if (buf.toString('latin1', 12, 16) !== 'IHDR') return null;

  const width = buf.readUInt32BE(16);
  const height = buf.readUInt32BE(20);
  if (width === 0 || height === 0) return null; // zero dimensions are invalid

  return { width, height };
}

module.exports = { parsePngIhdr, PNG_SIGNATURE };

