'use strict';

const path = require('node:path');
const fs = require('node:fs');
const crypto = require('node:crypto');
const express = require('express');
const multer = require('multer');
const { parsePngIhdr } = require('./png');

const MAX_FILE_SIZE = 500 * 1024; // 500 KB
const MAX_DIMENSION = 2048;
const FIELD_NAME = 'avatar';

const uploadDir = process.env.UPLOAD_DIR || path.join(__dirname, '..', 'uploads');

const storage = multer.diskStorage({
  destination: (_req, _file, cb) => cb(null, uploadDir),
  filename: (_req, _file, cb) =>
    cb(null, `${Date.now()}-${crypto.randomBytes(8).toString('hex')}.png`),
});

/** Uniform JSON error envelope: { ok:false, error:{ code, message } } */
function fail(res, status, code, message) {
  return res.status(status).json({ ok: false, error: { code, message } });
}

const upload = multer({
  storage,
  limits: { fileSize: MAX_FILE_SIZE },
  fileFilter: (_req, file, cb) => {
    if (file.mimetype && file.mimetype.startsWith('image/')) return cb(null, true);
    const err = new Error('only image/* files are allowed');
    err.code = 'bad_type';
    err.status = 415;
    cb(err);
  },
});

const app = express();
app.use(express.json());

app.post('/upload', (req, res, next) => {
  upload.single(FIELD_NAME)(req, res, (err) => {
    if (err instanceof multer.MulterError) {
      if (err.code === 'LIMIT_FILE_SIZE') {
        return fail(res, 413, 'too_large', `file exceeds ${MAX_FILE_SIZE} byte limit`);
      }
      // e.g. wrong multipart field name / too many parts
      return fail(res, 400, 'bad_request', err.code);
    }
    if (err) {
      if (err.code === 'bad_type') return fail(res, err.status, err.code, err.message);
      return next(err);
    }

    const file = req.file;
    if (!file) {
      return fail(res, 400, 'bad_request', `multipart field "${FIELD_NAME}" is required`);
    }

    // Post-acceptance validation: parse PNG IHDR by hand (no sharp).
    const header = fs.readFileSync(file.path).subarray(0, 24); // <=500KB, sync is fine
    const ihdr = parsePngIhdr(header);

    let cleanup = false;
    if (!ihdr) {
      cleanup = true;
      return fail(res, 415, 'bad_type', 'payload is not a decodable PNG image');
    }
    if (ihdr.width > MAX_DIMENSION || ihdr.height > MAX_DIMENSION) {
      cleanup = true;
      return fail(
        res,
        422,
        'too_big_dimensions',
        `dimensions ${ihdr.width}x${ihdr.height} exceed ${MAX_DIMENSION}x${MAX_DIMENSION}`
      );
    }

    res.status(201).json({
      ok: true,
      file: {
        fieldname: file.fieldname,
        filename: file.filename,
        mimetype: file.mimetype,
        size: file.size,
        width: ihdr.width,
        height: ihdr.height,
      },
    });

    // Rejected after acceptance -> do not keep the orphaned temp file on disk.
    if (cleanup) fs.unlink(file.path, () => {});
  });
});

// eslint-disable-next-line no-unused-vars
app.use((err, _req, res, _next) => {
  res.status(500).json({ ok: false, error: { code: 'internal', message: String(err.message) } });
});

module.exports = { app, uploadDir, MAX_FILE_SIZE, MAX_DIMENSION };

