'use strict';

const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const request = require('supertest');

// Upload dir must exist before the app module reads it.
const uploadDir = fs.mkdtempSync(path.join(os.tmpdir(), 'uploads-'));
process.env.UPLOAD_DIR = uploadDir;

const { app, MAX_FILE_SIZE } = require('../src/app');

/** PNG signature: 137 'P' 'N' 'G' '\r' '\n' 0x1A '\n' */
const SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

/**
 * Hand-craft a PNG buffer: 8-byte signature + IHDR chunk header.
 * The body after IHDR's width/height is filler; the dimension check only
 * needs the first 24 bytes to be well-formed. CRC is left as zeros on purpose.
 *
 * @param {number} width
 * @param {number} height
 * @param {object} [opts]
 * @param {number} [opts.pad] extra filler bytes appended after the IHDR fields
 * @returns {Buffer}
 */
function makePng(width, height, { pad = 16 } = {}) {
  const chunkLen = Buffer.alloc(4);
  chunkLen.writeUInt32BE(13, 0); // IHDR data length

  const ihdrType = Buffer.from('IHDR', 'ascii');
  const dims = Buffer.alloc(8);
  dims.writeUInt32BE(width, 0);
  dims.writeUInt32BE(height, 4);

  const tail = Buffer.alloc(5 + pad); // bit depth, color type, CRC placeholder, filler
  return Buffer.concat([SIG, chunkLen, ihdrType, dims, tail]);
}

test('rejects files over 500 KB with code too_large', async () => {
  const bigPng = Buffer.concat([
    makePng(64, 64),
    Buffer.alloc(MAX_FILE_SIZE), // pushes total past the limit
  ]);
  assert.ok(bigPng.length > MAX_FILE_SIZE);

  const res = await request(app)
    .post('/upload')
    .attach('avatar', bigPng, { filename: 'big.png', contentType: 'image/png' });

  assert.equal(res.status, 413);
  assert.equal(res.body.ok, false);
  assert.equal(res.body.error.code, 'too_large');
});

test('rejects non-image mimetypes with code bad_type', async () => {
  const res = await request(app)
    .post('/upload')
    .attach('avatar', Buffer.from('definitely not an image'), {
      filename: 'notes.txt',
      contentType: 'text/plain',
    });

  assert.equal(res.status, 415);
  assert.equal(res.body.ok, false);
  assert.equal(res.body.error.code, 'bad_type');
});

test('rejects PNG dimensions over 2048x2048 with code too_big_dimensions', async () => {
  // Small enough in bytes to pass the size limit, huge in declared dimensions.
  const res = await request(app)
    .post('/upload')
    .attach('avatar', makePng(3000, 3000), { filename: 'huge.png', contentType: 'image/png' });

  assert.equal(res.status, 422);
  assert.equal(res.body.ok, false);
  assert.equal(res.body.error.code, 'too_big_dimensions');
});

test('accepts a valid small PNG and saves it to disk', async () => {
  const res = await request(app)
    .post('/upload')
    .attach('avatar', makePng(1024, 768), { filename: 'ok.png', contentType: 'image/png' });

  assert.equal(res.status, 201);
  assert.equal(res.body.ok, true);
  assert.equal(res.body.file.width, 1024);
  assert.equal(res.body.file.height, 768);

  const savedPath = path.join(uploadDir, res.body.file.filename);
  assert.ok(fs.existsSync(savedPath), 'uploaded file should exist on disk');
  const saved = fs.readFileSync(savedPath);
  assert.deepEqual([...saved.subarray(0, 8)], [...SIG]); // PNG signature persisted
  assert.equal(saved.readUInt32BE(16), 1024); // IHDR width survived the round-trip
});

